func NewTop3skusValueNull() Top3skusValue {
	return Top3skusValue{
		state: attr.ValueStateNull,
	}
}

func NewTop3skusValueUnknown() Top3skusValue {
	return Top3skusValue{
		state: attr.ValueStateUnknown,
	}
}

func NewTop3skusValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (Top3skusValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing Top3skusValue Attribute Value",
				"While creating a Top3skusValue value, a missing attribute value was detected. "+
					"A Top3skusValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Top3skusValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid Top3skusValue Attribute Type",
				"While creating a Top3skusValue value, an invalid attribute value was detected. "+
					"A Top3skusValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Top3skusValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("Top3skusValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra Top3skusValue Attribute Value",
				"While creating a Top3skusValue value, an extra attribute value was detected. "+
					"A Top3skusValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra Top3skusValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewTop3skusValueUnknown(), diags
	}

	costAttribute, ok := attributes["cost"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`cost is missing from object`)

		return NewTop3skusValueUnknown(), diags
	}

	costVal, ok := costAttribute.(basetypes.Float64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`cost expected to be basetypes.Float64Value, was: %T`, costAttribute))
	}

	nameAttribute, ok := attributes["name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`name is missing from object`)

		return NewTop3skusValueUnknown(), diags
	}

	nameVal, ok := nameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`name expected to be basetypes.StringValue, was: %T`, nameAttribute))
	}

	if diags.HasError() {
		return NewTop3skusValueUnknown(), diags
	}

	return Top3skusValue{
		Cost:  costVal,
		Name:  nameVal,
		state: attr.ValueStateKnown,
	}, diags
}

func NewTop3skusValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) Top3skusValue {
	object, diags := NewTop3skusValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewTop3skusValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t Top3skusType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewTop3skusValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewTop3skusValueUnknown(), nil
	}

	if in.IsNull() {
		return NewTop3skusValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewTop3skusValueMust(Top3skusValue{}.AttributeTypes(ctx), attributes), nil
}

func (t Top3skusType) ValueType(ctx context.Context) attr.Value {
	return Top3skusValue{}
}

var _ basetypes.ObjectValuable = Top3skusValue{}

type Top3skusValue struct {
	Cost  basetypes.Float64Value `tfsdk:"cost"`
	Name  basetypes.StringValue  `tfsdk:"name"`
	state attr.ValueState
}

func (v Top3skusValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 2)

	var val tftypes.Value
	var err error

	attrTypes["cost"] = basetypes.Float64Type{}.TerraformType(ctx)
	attrTypes["name"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 2)

		val, err = v.Cost.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["cost"] = val

		val, err = v.Name.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["name"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v Top3skusValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v Top3skusValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v Top3skusValue) String() string {
	return "Top3skusValue"
}

func (v Top3skusValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"cost": basetypes.Float64Type{},
		"name": basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"cost": v.Cost,
			"name": v.Name,
		})

	return objVal, diags
}

func (v Top3skusValue) Equal(o attr.Value) bool {
	other, ok := o.(Top3skusValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Cost.Equal(other.Cost) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	return true
}

func (v Top3skusValue) Type(ctx context.Context) attr.Type {
	return Top3skusType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

func (v Top3skusValue) AttributeTypes(ctx context.Context) map[string]attr.Type {
	return map[string]attr.Type{
		"cost": basetypes.Float64Type{},
		"name": basetypes.StringType{},
	}
}
